import { graphql } from 'gatsby';
import React from 'react';
import styled from '@emotion/styled';
const StyledFrameWrap = styled.div`
  width: 100%;
  min-height: 100vh;
  /* position: relative; */
  iframe {
    border: none;
    height: 100vh;
  }
`;
const ResumePage = ({ data }: any) => {
  return (
    <StyledFrameWrap>
      <iframe
        src={data.strapiAbout.resumeLink}
        width="100%"
        height="100%"
      ></iframe>
    </StyledFrameWrap>
  );
};

export default ResumePage;

export const query = graphql`
  {
    strapiAbout {
      resumeLink
    }
  }
`;
